WITH metrics AS (SELECT *, AVG(monthly_fee) OVER (PARTITION BY customer_id ORDER BY end_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS monthly_fee_avg_6, LAG(monthly_fee, 1) OVER (ORDER BY end_date, id) AS prev_monthly_fee FROM subscriptions) SELECT customer_id, DATE_TRUNC('MONTH', end_date) AS activity_month, SUM(monthly_fee_avg_6) FILTER (WHERE status = 'EXPIRED') AS expired_total_monthly_fee_avg_6, COUNT(*) FILTER (WHERE status = 'EXPIRED') AS expired_rows, ROUND(SUM(monthly_fee_avg_6) / NULLIF(COUNT(CASE WHEN status = 'PAUSED' THEN 1 END), 0), 2) AS monthly_fee_avg_6_per_paused, APPROX_PERCENTILE(monthly_fee, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_quartiles FROM metrics GROUP BY customer_id, DATE_TRUNC('MONTH', end_date);
